package com.sibcraft.creeperborn.client;

import java.util.*;
import com.mojang.blaze3d.vertex.PoseStack;
import net.minecraft.client.model.geom.*;
import net.minecraft.client.model.geom.builders.*;
import net.minecraft.client.renderer.SubmitNodeCollector;
import net.minecraft.client.renderer.entity.state.AvatarRenderState;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.client.renderer.rendertype.RenderTypes;
import net.minecraft.resources.Identifier;
import org.joml.Quaternionf;

/** Original articulated fox, three/six-tail cloaks and pink axolotl meshes, using native block textures. */
public final class ZoanRenderer {
    private static Identifier tex(String name){return Identifier.withDefaultNamespace("textures/block/"+name+".png");}
    private static final Identifier ORANGE=tex("orange_concrete"),RED=tex("red_concrete"),GOLD=tex("yellow_concrete"),WHITE=tex("white_concrete"),BLACK=tex("black_concrete"),PINK=tex("pink_concrete"),MAGENTA=tex("magenta_concrete"),CYAN=tex("cyan_concrete"),PURPLE=tex("purple_concrete");
    private static void box(PartDefinition r,String n,float x,float y,float z,float w,float h,float d){r.addOrReplaceChild(n,CubeListBuilder.create().texOffs(0,0).addBox(x,y,z,w,h,d),PartPose.ZERO);}
    private static ModelPart bake(MeshDefinition mesh){return LayerDefinition.create(mesh,16,16).bakeRoot();}
    private static final ModelPart FOX=fox(false),FOX_DARK=fox(true),FOX_EYES=eyes(),TAIL=tail(),CLOAK=cloak(),MARKS=marks(),EARS=ears(),AX=axolotl(false),AX_DETAILS=axolotl(true),GILLS=gills(),ORB=orb(),CLAW=claw(),RING=ring();
    private static ModelPart fox(boolean dark){MeshDefinition m=new MeshDefinition();var r=m.getRoot();if(!dark){box(r,"chest",-14,24,-19,28,30,46);box(r,"shoulder",-16,32,7,32,27,21);var h=r.addOrReplaceChild("head",CubeListBuilder.create(),PartPose.offset(0,57,22));box(h,"skull",-13,-7,-8,26,23,24);box(h,"cheekL",-17,-9,0,8,12,19);box(h,"cheekR",9,-9,0,8,12,19);box(h,"muzzle",-8,-8,13,16,10,20);for(int side:new int[]{-1,1}){box(h,"ear"+side,side*9-4,14,-3,8,9,9);box(h,"earTip"+side,side*9-2.5f,22,-1,5,1,6);for(int z:new int[]{-15,18}){var leg=r.addOrReplaceChild("leg"+side+"_"+z,CubeListBuilder.create(),PartPose.offset(side*11,30,z));box(leg,"upper",-5,-19,-5,10,20,10);box(leg,"ankle",-3.5f,-28,-3,7,12,8);box(leg,"paw",-5,-30,-4,10,5,14);}}}else{box(r,"nose",-5,49,54,10,5,3);for(int side:new int[]{-1,1}){box(r,"brow"+side,side*8-5,63,38.2f,10,3,.6f);box(r,"eyeline"+side,side*9-1,57,38,2,7,1);box(r,"innerEar"+side,side*9-2.4f,73,25.2f,4.8f,6,.6f);for(int i=0;i<3;i++)box(r,"whisker"+side+i,side*(11+i*2)-1,51+i*3,41-i*3,2,2,5);}}return bake(m);}
    private static ModelPart eyes(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();for(int side:new int[]{-1,1})box(r,"eye"+side,side*8-2,59,38.4f,4,3,.7f);return bake(m);}
    private static ModelPart tail(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();for(int i=0;i<10;i++){float w=10-i*.75f;var next=r.addOrReplaceChild("next",CubeListBuilder.create(),PartPose.offset(0,0,-11));box(next,"fur",-w/2,-w/2,-12,w,w,13);r=next;}return bake(m);}
    private static ModelPart cloak(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();box(r,"chest",-4.4f,10,-2.5f,8.8f,12.5f,5);box(r,"collar",-5,21,-3,10,2,6);for(int side:new int[]{-1,1}){var a=r.addOrReplaceChild("arm"+side,CubeListBuilder.create(),PartPose.offset(side*5.8f,21,0));box(a,"sleeve",-2,-12,-2,4,12,4);box(a,"hand",-2.5f,-14,-2.5f,5,4,5);for(int i=0;i<3;i++)box(a,"claw"+i,-2+i*1.5f,-16,1,1,3,1.6f);var leg=r.addOrReplaceChild("leg"+side,CubeListBuilder.create(),PartPose.offset(side*2.1f,10,0));box(leg,"pant",-2,-10,-2,4,10,4);box(r,"coat"+side,side*4-2,7,-3,4,7,5.5f);}return bake(m);}
    private static ModelPart marks(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();box(r,"zipper",-.35f,10,2.55f,.7f,12,.2f);box(r,"belt",-4.5f,10,2.55f,9,.8f,.2f);for(int side:new int[]{-1,1}){box(r,"collarMark"+side,side*3-1,20,3.1f,2,1,.2f);for(int i=0;i<3;i++)box(r,"seal"+side+i,side*2.8f-.45f,18-i*1.7f,2.6f,.9f,1,.2f);}return bake(m);}
    private static ModelPart ears(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();for(int side:new int[]{-1,1}){box(r,"ear"+side,side*3-1.5f,30,-1,3,4,3);box(r,"tip"+side,side*3-1,33,-.5f,2,2,2);}return bake(m);}
    private static ModelPart axolotl(boolean detail){MeshDefinition m=new MeshDefinition();var r=m.getRoot();if(!detail){box(r,"body",-3,1,-6,6,5,11);box(r,"head",-4,1,3,8,6,7);var t=r.addOrReplaceChild("tail",CubeListBuilder.create(),PartPose.offset(0,3,-6));box(t,"base",-2,-1,-7,4,3,8);box(t,"tip",-1,-.8f,-13,2,2.6f,7);for(int side:new int[]{-1,1})for(int z:new int[]{-3,5}){var leg=r.addOrReplaceChild("leg"+side+"_"+z,CubeListBuilder.create(),PartPose.offset(side*2,2,z));box(leg,"foot",side<0?-3:0,-2,-1.5f,3,2,3);}}else{for(int side:new int[]{-1,1}){box(r,"eye"+side,side*2.4f-.55f,4.8f,10.05f,1.1f,1.1f,.15f);box(r,"cheek"+side,side*2.8f-.6f,2.8f,10.04f,1.2f,.6f,.15f);}box(r,"mouth",-1,2.4f,10.1f,2,.25f,.12f);box(r,"backFin",-.2f,5,-8,.4f,2,10);box(r,"tailFin",-.2f,2,-19,.4f,4,12);}return bake(m);}
    private static ModelPart gills(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();for(int side:new int[]{-1,1})for(int i=0;i<3;i++){var g=r.addOrReplaceChild("gill"+side+i,CubeListBuilder.create(),PartPose.offsetAndRotation(side*4,5,4+i*2,0,0,side*(-.5f+i*.45f)));box(g,"stem",side<0?-4:0,-.3f,-.25f,4,.6f,.5f);for(int j=1;j<=3;j++)box(g,"frond"+j,side*j-.2f,-1.1f,-.2f,.4f,2,.4f);}return bake(m);}
    private static ModelPart orb(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();box(r,"core",-6,-6,-6,12,12,12);box(r,"wide",-7,-4,-4,14,8,8);box(r,"tall",-4,-7,-4,8,14,8);return bake(m);}
    private static ModelPart claw(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();for(int i=0;i<3;i++){var q=r.addOrReplaceChild("slash"+i,CubeListBuilder.create(),PartPose.rotation(0,0,-.5f));box(q,"edge",i*4-5,-10,-.5f,1.2f,20,1);}return bake(m);}
    private static ModelPart ring(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();for(int i=0;i<32;i++){double a=i*Math.PI/16;var q=r.addOrReplaceChild("arc"+i,CubeListBuilder.create(),PartPose.offsetAndRotation((float)Math.cos(a)*8,(float)Math.sin(a)*8,0,0,0,(float)a));box(q,"edge",-.5f,-1,-.5f,1,2,1);}return bake(m);}
    private static void draw(ModelPart mesh,Identifier texture,PoseStack p,SubmitNodeCollector n,boolean glow){n.submitModelPart(mesh,p,glow?RenderTypes.eyes(texture):RenderTypes.entityTranslucent(texture),0xF000F0,OverlayTexture.NO_OVERLAY,null);}
    private static void tails(PoseStack p,SubmitNodeCollector n,int mode,float age){int count=com.sibcraft.creeperborn.ZoanPowers.tailCount(mode);for(int i=0;i<count;i++){p.pushPose();float fan=count==1?0:(i/(float)(count-1)-.5f)*2.3f;p.translate(0,mode==3?2.8:.65,mode==3?-1.35:-.15);p.rotate(new Quaternionf().rotationYXZ(fan,.8f+(float)Math.sin(age*.045+i*.7)*.08f,0));float scale=mode==3?1:mode==2?.38f:.28f;p.scale(scale,scale,scale);ModelPart part=TAIL;for(int k=0;k<10;k++){part=part.getChild("next");part.xRot=-.035f+(float)Math.sin(age*.055+i*.8+k*.35)*.025f;part.yRot=(float)Math.sin(age*.04+i+k*.22)*.035f;}draw(TAIL,mode==1?RED:mode==2?GOLD:ORANGE,p,n,mode!=3);if(mode!=3){p.pushPose();p.scale(.72f,.72f,1);draw(TAIL,mode==1?ORANGE:WHITE,p,n,true);p.popPose();}p.popPose();}}
    public static boolean full(int flags){return ((flags>>2)&3)==3||(flags&3)==2&&((flags>>2)&3)==1;}
    public static void avatar(AvatarRenderState state,PoseStack p,SubmitNodeCollector n,int flags){int mode=(flags>>2)&3;if(mode==0)return;boolean fox=(flags&3)==1;float age=state.ageInTicks;p.pushPose();p.rotate(new Quaternionf().rotationY((float)Math.toRadians(-state.bodyRot)));if(fox){if(mode==3){float gait=(float)Math.sin(age*.23)*.16f;for(int side:new int[]{-1,1})for(int z:new int[]{-15,18})FOX.getChild("leg"+side+"_"+z).xRot=gait*side*(z<0?-1:1);draw(FOX,ORANGE,p,n,false);draw(FOX_DARK,BLACK,p,n,false);draw(FOX_EYES,RED,p,n,true);}else{for(int side:new int[]{-1,1}){CLOAK.getChild("arm"+side).xRot=(float)Math.sin(age*.12+side)*.1f;CLOAK.getChild("leg"+side).xRot=(float)Math.sin(age*.12)*side*.08f;}draw(CLOAK,mode==1?RED:GOLD,p,n,true);draw(EARS,mode==1?RED:ORANGE,p,n,true);if(mode==2)draw(MARKS,BLACK,p,n,false);}tails(p,n,mode,age);}else if(mode==1||mode==3){float size=mode==3?6:1;p.scale(size,size,size);AX.getChild("tail").yRot=(float)Math.sin(age*.25)*.22f;for(int side:new int[]{-1,1})for(int z:new int[]{-3,5})AX.getChild("leg"+side+"_"+z).yRot=(float)Math.sin(age*.28+side+(z<0?Math.PI:0))*.25f;draw(AX,PINK,p,n,false);draw(AX_DETAILS,BLACK,p,n,false);draw(GILLS,MAGENTA,p,n,false);}else{p.pushPose();p.translate(0,1.15,.08);p.scale(1.05f,1.05f,1.05f);draw(GILLS,MAGENTA,p,n,false);p.popPose();p.pushPose();p.translate(0,.4,-.1);p.rotate(new Quaternionf().rotationX(.7f));p.scale(1.2f,1.2f,1.2f);draw(AX,PINK,p,n,false);p.popPose();}if((flags&64)!=0){p.pushPose();p.translate(0,mode==3?1.6:.6,mode==3?2.8:1);float scale=mode==3?3:1;p.scale(scale,scale,scale);p.rotate(new Quaternionf().rotationZ(age*.1f));draw(RING,CYAN,p,n,true);p.popPose();}p.popPose();}
    public static void effect(int kind,float age,PoseStack p,SubmitNodeCollector n){p.pushPose();if(kind==28){draw(ORB,BLACK,p,n,false);for(int i=0;i<3;i++){p.pushPose();p.rotate(new Quaternionf().rotationXYZ(age*.08f+i,age*.13f+i,age*.06f));float size=1.15f+i*.13f;p.scale(size,size,size);draw(RING,i==1?RED:PURPLE,p,n,true);p.popPose();}}else if(kind==29){draw(ORB,ORANGE,p,n,true);p.scale(.65f,.65f,.65f);draw(ORB,GOLD,p,n,true);}else if(kind==30){p.scale(1.2f,1.2f,1);draw(CLAW,RED,p,n,true);}else if(kind==31){draw(ORB,CYAN,p,n,true);p.scale(.65f,.65f,1.2f);draw(ORB,WHITE,p,n,true);}else if(kind==32){float size=Math.max(.05f,Math.min(1,age/12));p.scale(size,size,size);draw(ORB,WHITE,p,n,true);for(int i=0;i<3;i++){p.pushPose();p.rotate(new Quaternionf().rotationXYZ(i*.9f,age*.07f+i,0));p.scale(2,2,2);draw(RING,i==1?RED:PURPLE,p,n,true);p.popPose();}}p.popPose();}
    public static List<Identifier> textures(){return List.of(ORANGE,RED,GOLD,WHITE,BLACK,PINK,MAGENTA,CYAN,PURPLE);}
    public static void validate(){FOX.getChild("head").getChild("muzzle");AX.getChild("tail").getChild("tip");GILLS.getChild("gill-12").getChild("frond3");ModelPart t=TAIL;for(int i=0;i<10;i++)t=t.getChild("next");if(com.sibcraft.creeperborn.ZoanPowers.tailCount(1)!=3||com.sibcraft.creeperborn.ZoanPowers.tailCount(3)!=9)throw new AssertionError("Fox tail progression");}
}
